            throw ex.get();
          }
        }
      }
    }

    public Optional<Boolean> getMatch() {
      return match;
    }

    public Observation<T> getControl() {
      return control;
    }

    public Optional<Observation<T>> getCandidate() {
      return candidate;
    }

    public Map<String, Object> getContext() {
      return context;
    }
}
